insert into public.learning_paths (slug, title, objective, level, status) values ('debuter-cartographie-libre', '{"fr":"Débuter en cartographie libre","en":"Getting started with open mapping"}'::jsonb, '{"fr":"Savoir contribuer à OpenStreetMap puis produire une première carte thématique dans QGIS.","en":"Contribute to OpenStreetMap, then produce a first thematic map in QGIS."}'::jsonb, 'beginner', 'published') on conflict (slug) do nothing;
insert into public.learning_path_steps (path_id, position, resource_id, instruction) select lp.id, 1, (select id from public.resources where slug = 'learnosm'), '{"fr":"Suivez le chapitre « Débuter » et faites vos premières modifications.","en":"Follow the \"Beginner\" chapter and make your first edits."}'::jsonb from public.learning_paths lp where lp.slug = 'debuter-cartographie-libre' and not exists (select 1 from public.learning_path_steps s where s.path_id = lp.id and s.position = 1);
insert into public.learning_path_steps (path_id, position, resource_id, instruction) select lp.id, 2, (select id from public.resources where slug = 'qgis-training-manual'), '{"fr":"Réalisez les modules sur l''interface et les données vecteur.","en":"Complete the interface and vector data modules."}'::jsonb from public.learning_paths lp where lp.slug = 'debuter-cartographie-libre' and not exists (select 1 from public.learning_path_steps s where s.path_id = lp.id and s.position = 2);
insert into public.learning_path_steps (path_id, position, resource_id, instruction) select lp.id, 3, (select id from public.resources where slug = 'natural-earth'), '{"fr":"Téléchargez les limites administratives et composez une carte de votre pays.","en":"Download administrative boundaries and lay out a map of your country."}'::jsonb from public.learning_paths lp where lp.slug = 'debuter-cartographie-libre' and not exists (select 1 from public.learning_path_steps s where s.path_id = lp.id and s.position = 3);
insert into public.learning_paths (slug, title, objective, level, status) values ('devenir-data-analyst', '{"fr":"Devenir Data Analyst","en":"Becoming a Data Analyst"}'::jsonb, '{"fr":"Passer des bases statistiques à un projet d’analyse complet, de la donnée brute au tableau de bord.","en":"Go from statistical basics to a complete analysis project, from raw data to dashboard."}'::jsonb, 'beginner', 'published') on conflict (slug) do nothing;
insert into public.learning_path_steps (path_id, position, resource_id, instruction) select lp.id, 1, (select id from public.resources where slug = 'khan-academy-statistiques-probabilites'), '{"fr":"Étape 0 — Apprendre la statistique de base et comprendre les données avant de les analyser. Ne saute pas cette étape.","en":"Step 0 — Learn basic statistics and understand data before analysing it. Do not skip this step."}'::jsonb from public.learning_paths lp where lp.slug = 'devenir-data-analyst' and not exists (select 1 from public.learning_path_steps s where s.path_id = lp.id and s.position = 1);
insert into public.learning_path_steps (path_id, position, resource_id, instruction) select lp.id, 2, (select id from public.resources where slug = 'microsoft-excel-aide-formation'), '{"fr":"Étape 1 — Excel avancé : la référence et le premier outil de tout analyste.","en":"Step 1 — Advanced Excel: the reference and every analyst’s first tool."}'::jsonb from public.learning_paths lp where lp.slug = 'devenir-data-analyst' and not exists (select 1 from public.learning_path_steps s where s.path_id = lp.id and s.position = 2);
insert into public.learning_path_steps (path_id, position, resource_id, instruction) select lp.id, 3, (select id from public.resources where slug = 'sqlbolt'), '{"fr":"Étape 2 — SQL : interroger, filtrer et croiser des bases de données.","en":"Step 2 — SQL: query, filter and join databases."}'::jsonb from public.learning_paths lp where lp.slug = 'devenir-data-analyst' and not exists (select 1 from public.learning_path_steps s where s.path_id = lp.id and s.position = 3);
insert into public.learning_path_steps (path_id, position, resource_id, instruction) select lp.id, 4, (select id from public.resources where slug = 'kaggle-learn'), '{"fr":"Étape 3 — Python et Pandas : automatiser et passer à l’échelle.","en":"Step 3 — Python and Pandas: automate and scale."}'::jsonb from public.learning_paths lp where lp.slug = 'devenir-data-analyst' and not exists (select 1 from public.learning_path_steps s where s.path_id = lp.id and s.position = 4);
insert into public.learning_path_steps (path_id, position, resource_id, instruction) select lp.id, 5, (select id from public.resources where slug = 'microsoft-learn-power-bi'), '{"fr":"Étape 4a — Power BI : transformer des chiffres en tableaux de bord clairs pour les décideurs.","en":"Step 4a — Power BI: turn figures into clear dashboards for decision-makers."}'::jsonb from public.learning_paths lp where lp.slug = 'devenir-data-analyst' and not exists (select 1 from public.learning_path_steps s where s.path_id = lp.id and s.position = 5);
insert into public.learning_path_steps (path_id, position, resource_id, instruction) select lp.id, 6, (select id from public.resources where slug = 'tableau-public-how-to-videos'), '{"fr":"Étape 4b — Tableau Public : alternative gratuite pour la visualisation.","en":"Step 4b — Tableau Public: a free alternative for visualisation."}'::jsonb from public.learning_paths lp where lp.slug = 'devenir-data-analyst' and not exists (select 1 from public.learning_path_steps s where s.path_id = lp.id and s.position = 6);
insert into public.learning_path_steps (path_id, position, resource_id, instruction) select lp.id, 7, (select id from public.resources where slug = 'learn-prompting'), '{"fr":"Étape 5 — Accélérer avec l’IA : écrire du code, déboguer, comprendre un jeu de données. L’IA ne remplace pas l’analyste.","en":"Step 5 — Speed up with AI: write code, debug, understand a dataset. AI does not replace the analyst."}'::jsonb from public.learning_paths lp where lp.slug = 'devenir-data-analyst' and not exists (select 1 from public.learning_path_steps s where s.path_id = lp.id and s.position = 7);
insert into public.learning_path_steps (path_id, position, resource_id, instruction) select lp.id, 8, (select id from public.resources where slug = 'kaggle-datasets'), '{"fr":"Étape finale — Un projet concret de A à Z : choisir un sujet, trouver des données, les nettoyer, les analyser, construire un tableau de bord et raconter une histoire.","en":"Final step — A complete project: pick a topic, find data, clean it, analyse it, build a dashboard and tell a story."}'::jsonb from public.learning_paths lp where lp.slug = 'devenir-data-analyst' and not exists (select 1 from public.learning_path_steps s where s.path_id = lp.id and s.position = 8);
